{
  "lecture": [
    {
      "etiquette": "F26",
      "R1": {
        "valeur": 1,
        "passage": "la course coupée en moitiés couvre en moyenne sur les vingt mondes au moins 10 % de composantes plantées de plus que la course témoin"
      },
      "R2": {
        "valeur": 1,
        "passage": "lu par l'oracle après chaque course : composantes plantées couvertes (conditionnelles et autres, comptées à part), lois fausses et copies promues"
      },
      "R3": {
        "valeur": 1,
        "passage": "le nul mis à jour refuse comme copie toute carte de B qui reprend une loi retenue en A."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "L'orchestrateur joue chaque génération en deux moitiés. Moitié A : un appel par proposeur, en session neuve, pour trois cartes"
      },
      "R6": {
        "valeur": 1,
        "passage": "environ 225 USD pour vingt mondes et deux bras au budget de quatre générations du témoin (près de 1,4 USD par génération)"
      },
      "R7": {
        "valeur": 1,
        "passage": "La seconde moitié peut proposer ce qui dépend d'une condition retenue dans la première, au lieu d'attendre la génération suivante."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F27",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues en fin de course augmente d'au moins 20 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes et dans les retenues, nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "Insérer cette table factuelle en annexe de la liste intégrale des lois de l'archive dans la vue publique, sans ajouter aucune consigne prescriptive, ni quota, ni score."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "pour chaque trait public t_i du monde, l'entier n(t_i) égal au nombre de lois de l'archive où le symbole t_i apparaît"
      },
      "R6": {
        "valeur": 1,
        "passage": "une seule passe d'appels aux proposeurs avec la vue augmentée de la table syntaxique (quelques dollars d'appels)"
      },
      "R7": {
        "valeur": 0,
        "motif": "La table sans consigne peut aussi bien renforcer l'ancrage sur les traits fréquents qu'encourager les traits absents, comme le reconnaît la fiche, donc le mécanisme n'implique pas le signe prédit."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F28",
      "R1": {
        "valeur": 1,
        "passage": "Copies et lois fausses promues (oracle) divisées par au moins 2 sur la somme"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : fausses, copies, composantes couvertes, par étage ; coût : calcul local seul, nombre de tirages frais égal ; témoin = nul actuel."
      },
      "R3": {
        "valeur": 0,
        "motif": "Calculer la valeur e contre un mélange fixe des lois du nul ne garantit pas une espérance au plus 1 sous chacune de ces lois, contrairement à la garantie composite exigée."
      },
      "R4": {
        "valeur": 1,
        "passage": "la valeur e d'une carte est calculée contre le mélange à poids fixes (règle écrite) de ces lois, ce qui conserve E[e] ≤ 1 sous le nul composite"
      },
      "R5": {
        "valeur": 0,
        "motif": "La grille de coupure et la règle des poids du mélange sont annoncées comme fixées mais ne sont pas définies dans la fiche."
      },
      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues ; quelques heures de calcul local."
      },
      "R7": {
        "valeur": 0,
        "motif": "L'élargissement peut absorber les composantes conditionnelles vraies et le mélange proposé n'assure pas la garantie composite invoquée, donc le mécanisme n'implique pas la baisse des copies avec maintien de la couverture."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F29",
      "R1": {
        "valeur": 1,
        "passage": "la part des réécritures adoptées qui battent vraiment la consigne précédente sur des mondes frais du vivier au moins doublée par rapport à la règle \" garder si le score a monté \""
      },
      "R2": {
        "valeur": 1,
        "passage": "réécritures adoptées qui ne battent pas la consigne précédente sur des mondes frais du vivier (oracle) ; composantes plantées couvertes sur la famille jamais vue (oracle)"
      },
      "R3": {
        "valeur": 1,
        "passage": "L'oracle du vivier de conception donne une différence vraie à chaque monde : l'e-processus parie sur une quantité exacte, sans note de juge"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "met à jour la richesse W ← W·(1 + λ·d) avec λ = 0,5 ; adoption dès que W ≥ 20 (niveau 0,05 par décision) ; abandon au plus après 40 mondes ; rien n'est adopté sans franchissement."
      },
      "R6": {
        "valeur": 1,
        "passage": "rejouable sur les journaux de conception déjà écrits, environ 6 heures de processeur ; si les journaux manquent, quelques mondes neufs, de l'ordre de 30 USD"
      },
      "R7": {
        "valeur": 1,
        "passage": "On peut arrêter tôt, et la probabilité de fausse adoption reste bornée par décision, même sous arrêt optionnel. Cette porte remplace la règle \" garder si le score a monté \"."
      },
      "N": {
        "valeur": "C7",
        "passage_fiche": "Chaque réécriture candidate est comparée à la consigne en place sur les mêmes mondes du vivier. Elle n'est adoptée que lorsqu'un e-processus par paris accumule une preuve décisive.",
        "passage_catalogue": "chaque candidate est comparée à la version en place **sur les mêmes instances**, et adoptée seulement quand un **e-processus par paris** accumule une preuve décisive"
      }
    },
    {
      "etiquette": "F30",
      "R1": {
        "valeur": 1,
        "passage": "À dollars égaux, la part des composantes conditionnelles couvertes par les retenues après 2 générations passe d'au plus 10 % pour le témoin à au moins 30 % pour le bras tableau croisé."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois : composantes conditionnelles et non conditionnelles couvertes, aux trois étages ; lois fausses et copies promues. Coût : dollars et jetons d'entrée par modèle."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le tableau n'est ni un verdict, ni l'oracle, ni la loi plantée, ni un score de juge ou de moniteur : ce sont des effectifs bruts d'épisodes publics."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Chaque trait continu est coupé à sa médiane sur cet échantillon. Pour chaque paire non ordonnée de traits, le tableau donne les effectifs et la fréquence de chaque issue dans les quatre cases."
      },
      "R6": {
        "valeur": 1,
        "passage": "Bon marché d'abord : un modèle peu cher, 20 mondes, 3 bras (témoin, croisé, placebo), 2 générations, environ 400 appels, soit des dizaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Elle laisse en revanche une pente de signe opposé dans les deux branches d'un croisement à deux traits. Un proposeur qui voit ce croisement peut la proposer avant même que sa condition soit archivée."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
